import {BIKES,Circuit,TRACKS,clamp} from './simulation.js';
export const BOT_DRIVERS=[{name:'L. ROSSI',number:46},{name:'M. SERRA',number:63},{name:'A. TORRES',number:89},{name:'D. COSTA',number:23},{name:'N. MARTIN',number:12},{name:'E. MORETTI',number:21},{name:'S. HAYES',number:41}];
export function makeBotRoster(humans,enabled){return enabled?Array.from({length:Math.max(0,8-humans)},(_,i)=>({id:'bot-'+i,...BOT_DRIVERS[i],bikeId:BIKES[(humans+i+2)%BIKES.length].id,livery:'factory',slot:humans+i,isBot:true,ready:true,finishTime:null,penalties:0,dnf:false})):[];}
export const botRate=flag=>flag==='red'?0:flag==='vsc'?.30:flag==='yellow'?.60:1;
export function appendBotPhase(phases,elapsed,flag){const rate=botRate(flag),last=phases.at(-1),at=Math.max(last?.at||0,Number(elapsed)||0);if(last&&Math.abs(last.at-at)<1e-7){last.rate=rate;return;}if(!last||last.rate!==rate)phases.push({at,rate});}
export function botClock(elapsed,phases=[{at:0,rate:1}]){let time=0,rate=1,at=0;for(const p of phases){if(p.at>elapsed)break;time+=Math.max(0,p.at-at)*rate;at=p.at;rate=p.rate;}time+=Math.max(0,elapsed-at)*rate;return{time,rate};}
function clockInverse(target,phases){let time=0,at=0,rate=1;for(const p of phases){const next=time+Math.max(0,p.at-at)*rate;if(rate>0&&target<=next)return at+(target-time)/rate;time=next;at=p.at;rate=p.rate;}return rate>0?at+(target-time)/rate:Infinity;}
export class BotGrid{
 constructor(track,options,humans){this.track=track;this.options=options;this.roster=makeBotRoster(humans,options.bots);this.profiles=this.roster.map((b,i)=>this.profile(b,i));}
 profile(bot,index){const tr=this.track,bike=BIKES.find(b=>b.id===bot.bikeId),start=-10-bot.slot*7,finish=tr.length*this.options.laps,n=Math.ceil((finish-start)/5),step=(finish-start)/n,positions=new Float64Array(n+1),speeds=new Float64Array(n+1),times=new Float64Array(n+1),wet=this.options.weather==='rain'?.74:1,pace=.94*(1-index*.014),top=Math.min(bike.top,300-index*3.3)/3.6;
  for(let i=0;i<=n;i++){positions[i]=start+i*step;speeds[i]=Math.min(top,tr.targetSpeed(positions[i],wet*Math.pow(bike.grip,.35),pace));}
  for(let i=n-1;i>=0;i--)speeds[i]=Math.min(speeds[i],Math.sqrt(speeds[i+1]**2+2*14*wet*step));speeds[0]=0;
  for(let i=1;i<=n;i++){const accel=Math.max(2.5,(8.5-3.8*speeds[i-1]/top)*bike.accel);speeds[i]=Math.min(speeds[i],Math.sqrt(speeds[i-1]**2+2*accel*step));times[i]=times[i-1]+2*step/Math.max(.01,speeds[i-1]+speeds[i]);}
  return{positions,speeds,times,duration:times[n],finish};
 }
 sample(elapsed,phases=[{at:0,rate:1}],finished=false){const clock=botClock(Math.max(0,elapsed),phases),tr=this.track;return this.roster.map((bot,index)=>{const p=this.profiles[index],end=clock.time>=p.duration;let s=p.finish,speed=0;if(!end){let lo=0,hi=p.times.length-1;while(hi-lo>1){const m=(lo+hi)>>1;if(p.times[m]<=clock.time)lo=m;else hi=m;}const dt=clamp(clock.time-p.times[lo],0,p.times[hi]-p.times[lo]),accel=(p.speeds[hi]-p.speeds[lo])/Math.max(.001,p.times[hi]-p.times[lo]);s=p.positions[lo]+p.speeds[lo]*dt+.5*accel*dt*dt;speed=(p.speeds[lo]+accel*dt)*clock.rate;}
   const phase=index*2.37,k=tr.sample(s+25).k,offset=clamp(Math.sin(s*.005+phase)*1.9+Math.tanh(k*160)*1.4,-5.8,5.8),q=tr.sample(s,offset),lean=clamp(Math.atan(speed*speed*tr.sample(s).k/9.81),-1.04,1.04),dnf=finished&&!end;return{...bot,progress:s,offset,finishTime:end?clockInverse(p.duration,phases):null,dnf,pose:{x:q.x,z:q.z,y:q.y,heading:q.yaw,speed:dnf?0:speed,lean,pitch:-Math.atan(q.grade||0),wheelie:0,crash:0,travel:Math.max(0,s-(-10-bot.slot*7))}};
  });}
}
export function networkBots(client,s=client.state){if(!s?.options.bots)return[];if(s.status==='lobby')return makeBotRoster(s.players.length,true);const humans=s.gridHumans??s.players.length,key=[s.roundId,s.options.trackId,s.options.weather,s.options.laps,humans].join(':');if(client.botGridKey!==key){client.botGridKey=key;client.botGrid=new BotGrid(new Circuit(TRACKS.find(t=>t.id===s.options.trackId)),s.options,humans);client.botFinishSent=new Set();}const elapsed=s.status==='finished'||s.flag==='red'?s.elapsed:s.elapsed+clamp((client.now()-s.now)/1000,0,2);return client.botGrid.sample(elapsed,s.botPhases,s.status==='finished');}
